import{_ as r,c as e,a as t,am as i}from"./chunks/framework.CTSvgyA8.js";const l="/docs/assets/03userManual_hr_04_02_19.Cga3Q0hL.png",o="/docs/assets/03userManual_hr_04_02_16.D8lA9Uml.png",h="/docs/assets/03userManual_hr_04_02_18.C8mMAKVS.png",n="/docs/assets/03userManual_hr_04_02_20.DxlNx8RM.png",g=JSON.parse('{"title":"중간  /  퇴직급여 계산","description":"","frontmatter":{},"headers":[],"relativePath":"manual/manual_hr_04_02/hra/hra5150.md","filePath":"manual/manual_hr_04_02/hra/hra5150.md"}'),s={name:"manual/manual_hr_04_02/hra/hra5150.md"};function u(d,a,_,c,b,m){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="중간-퇴직급여-계산" tabindex="-1">중간 / 퇴직급여 계산 <a class="header-anchor" href="#중간-퇴직급여-계산" aria-label="Permalink to &quot;중간  /  퇴직급여 계산&quot;">​</a></h1><table class="no-stripe"><tr><th><strong> Program ID</strong></th><td> HRA5150</td><th><strong> Program Name</strong></th><td> 중간 / 퇴직급여 계산</td></tr><tr><th><strong> Overview</strong></th><td colspan="3"> 퇴직정산기준등록 화면</td></tr><tr><th><strong> 메뉴 경로</strong></th><td colspan="3"> 인사관리 &gt; 정산관리 &gt; 퇴직정산 &gt; 중간 / 퇴직급여 계산 - 회계처리 탭</td></tr></table><p><img src="'+l+'" alt="" data-zoomable="true"></p><h2 id="사용설명" tabindex="-1">사용설명 <a class="header-anchor" href="#사용설명" aria-label="Permalink to &quot;사용설명&quot;">​</a></h2><h3 id="_1-정산일자-입력" tabindex="-1">1. 정산일자 입력 <a class="header-anchor" href="#_1-정산일자-입력" aria-label="Permalink to &quot;1. 정산일자 입력&quot;">​</a></h3><ul><li>[정산시작일~정산종료일]을 입력한다.</li></ul><h3 id="_2-퇴직정산구분을-선택하고-조회-버튼을-클릭한다" tabindex="-1">2. 퇴직정산구분을 선택하고 [조회] 버튼을 클릭한다. <a class="header-anchor" href="#_2-퇴직정산구분을-선택하고-조회-버튼을-클릭한다" aria-label="Permalink to &quot;2. 퇴직정산구분을 선택하고 [조회] 버튼을 클릭한다.&quot;">​</a></h3><ul><li><strong>퇴직정산</strong> : 최종 퇴직일 경우 선택(DB형,연금미가입자)</li><li><strong>중간정산</strong> : 중도정산일 경우 선택(DB형, 연금미가입자)</li><li><strong>퇴직정산(DC형)</strong> : DC형 가입자 중 최종 퇴직일 경우</li><li><strong>중간정산(DC형)</strong> : DC형 가입자 중 중간정산일 경우</li></ul><h3 id="_3-퇴직정산구분에-따라-대상자가-표시된다" tabindex="-1">3. 퇴직정산구분에 따라 대상자가 표시된다. <a class="header-anchor" href="#_3-퇴직정산구분에-따라-대상자가-표시된다" aria-label="Permalink to &quot;3. 퇴직정산구분에 따라 대상자가 표시된다.&quot;">​</a></h3><ul><li><strong>퇴직정산</strong> : 정산기간 내 퇴직자 표시</li><li><strong>중간정산</strong> : 현재 재직자 표시</li><li><strong>퇴직정산(DC형)</strong> : DC형 가입자 중 퇴직자 표시</li><li><strong>중간정산(DC형)</strong> : DC형 가입자 중 현재 재직자 표시</li></ul><h3 id="_4-일괄계산" tabindex="-1">4. 일괄계산 <a class="header-anchor" href="#_4-일괄계산" aria-label="Permalink to &quot;4. 일괄계산&quot;">​</a></h3><ul><li>대상자를 선택[체크박스 선택]한다.</li><li>정산일(퇴직자일 경우 퇴직일, 중간정산일 경우 중간정산일]을 입력한다.</li><li>[과세계산여부, 중간지급포함] 항목에 체크하고 [일괄계산] 버튼을 클릭한다.</li></ul><h3 id="_5-정산기본-정보가-생성된다" tabindex="-1">5. 정산기본 정보가 생성된다. <a class="header-anchor" href="#_5-정산기본-정보가-생성된다" aria-label="Permalink to &quot;5. 정산기본 정보가 생성된다.&quot;">​</a></h3><h3 id="_6-금액-산출-금액-입력-및-수정" tabindex="-1">6. 금액 산출, 금액 입력 및 수정 <a class="header-anchor" href="#_6-금액-산출-금액-입력-및-수정" aria-label="Permalink to &quot;6. 금액 산출, 금액 입력 및 수정&quot;">​</a></h3><ul><li>[평균급여, 평균상여, 연차수당, 국민연금전환금 등] 금액을 산출한다.</li><li>[지급배수, 누진일수, 연차수당, 퇴직위로금, 제외월수, 가산월수, 국민연금전환금, 퇴직추계액]을 입력 및 수정할 수 있다.</li></ul><h3 id="_7-퇴직-전-3개월-급여내역을-추가-수정할-수-있다" tabindex="-1">7. 퇴직 전 3개월 급여내역을 추가/수정할 수 있다. <a class="header-anchor" href="#_7-퇴직-전-3개월-급여내역을-추가-수정할-수-있다" aria-label="Permalink to &quot;7. 퇴직 전 3개월 급여내역을 추가/수정할 수 있다.&quot;">​</a></h3><ul><li>[행추가/행삭제] 버튼을 이용하여 귀속년월 등 수정</li><li>[적용금액]이 상이할 경우 수정하여 반영</li><li>적용시작일~적용종료일 수정하여 반영</li></ul><h3 id="_8-상여내역-추가-수정" tabindex="-1">8. 상여내역 추가/수정 <a class="header-anchor" href="#_8-상여내역-추가-수정" aria-label="Permalink to &quot;8. 상여내역 추가/수정&quot;">​</a></h3><ul><li>퇴직 전 1년 이내의 상여내역을 추가/수정할 수 있다.</li></ul><h3 id="_9-퇴직위로금" tabindex="-1">9. 퇴직위로금 <a class="header-anchor" href="#_9-퇴직위로금" aria-label="Permalink to &quot;9. 퇴직위로금&quot;">​</a></h3><ul><li>명예퇴직금, 위로금, 추가 지급금에 대하여 [퇴직위로금 등] 항목에 입력 시 퇴직급여에 합산처리 된다.</li></ul><h3 id="_10-퇴직추계액-금액을-입력할-수-있다" tabindex="-1">10. [퇴직추계액] 금액을 입력할 수 있다. <a class="header-anchor" href="#_10-퇴직추계액-금액을-입력할-수-있다" aria-label="Permalink to &quot;10. [퇴직추계액] 금액을 입력할 수 있다.&quot;">​</a></h3><h3 id="_11-국민연금전환금-이-있을-경우-기본적으로-가져오며-수정-가능하다" tabindex="-1">11. [국민연금전환금]이 있을 경우 기본적으로 가져오며, 수정 가능하다. <a class="header-anchor" href="#_11-국민연금전환금-이-있을-경우-기본적으로-가져오며-수정-가능하다" aria-label="Permalink to &quot;11. [국민연금전환금]이 있을 경우 기본적으로 가져오며, 수정 가능하다.&quot;">​</a></h3><h3 id="_12-퇴직급여가-산출된다" tabindex="-1">12. 퇴직급여가 산출된다. <a class="header-anchor" href="#_12-퇴직급여가-산출된다" aria-label="Permalink to &quot;12. 퇴직급여가 산출된다.&quot;">​</a></h3><h3 id="_13-내용을-수정하였을-경우-과세재계산-에-체크하고-저장하면-퇴직소득세-등이-재계산-된다" tabindex="-1">13. 내용을 수정하였을 경우 [과세재계산]에 체크하고 저장하면 퇴직소득세 등이 재계산 된다. <a class="header-anchor" href="#_13-내용을-수정하였을-경우-과세재계산-에-체크하고-저장하면-퇴직소득세-등이-재계산-된다" aria-label="Permalink to &quot;13. 내용을 수정하였을 경우 [과세재계산]에 체크하고 저장하면 퇴직소득세 등이 재계산 된다.&quot;">​</a></h3><hr><br><p><img src="'+l+'" alt="" data-zoomable="true"></p><h2 id="사용설명-1" tabindex="-1">사용설명 <a class="header-anchor" href="#사용설명-1" aria-label="Permalink to &quot;사용설명&quot;">​</a></h2><h3 id="_1-임원-퇴직자" tabindex="-1">1. 임원 퇴직자 <a class="header-anchor" href="#_1-임원-퇴직자" aria-label="Permalink to &quot;1. 임원 퇴직자&quot;">​</a></h3><ul><li>퇴직자가 임원일 경우 [임금 환산 년수]에 직위별 체제기간이 표시되며, 직위별 적용기간, 근무일수, 지급배수, 환산개월수가 산출된다.</li></ul><h3 id="_2-항목-수정-및-직위-변경" tabindex="-1">2.항목 수정 및 직위 변경 <a class="header-anchor" href="#_2-항목-수정-및-직위-변경" aria-label="Permalink to &quot;2.항목 수정 및 직위 변경&quot;">​</a></h3><ul><li>[직위, 적용시작일, 적용종료일, 지급배수]를 수정할 수 있으며, [직위] 변경 시 [지급배수, 환산개월수]가 변경된다.</li></ul><h3 id="_3-적용-정산-날짜-설정" tabindex="-1">3. 적용, 정산 날짜 설정 <a class="header-anchor" href="#_3-적용-정산-날짜-설정" aria-label="Permalink to &quot;3. 적용, 정산 날짜 설정&quot;">​</a></h3><ul><li>[적용시작일]은 [정산시작일] 보다 작을 수 없으며, [적용종료일]은 [정산종료일] 보다 클 수 없다.</li></ul><h3 id="_4-환산개월수" tabindex="-1">4. 환산개월수 <a class="header-anchor" href="#_4-환산개월수" aria-label="Permalink to &quot;4. 환산개월수&quot;">​</a></h3><ul><li>환산개월수 = [적용시작일~적용종료일] 개월 수 * [지급배수] [ex.78.12345]</li></ul><h3 id="_5-퇴직급여-소득세액-재계산" tabindex="-1">5. 퇴직급여, 소득세액 재계산 <a class="header-anchor" href="#_5-퇴직급여-소득세액-재계산" aria-label="Permalink to &quot;5. 퇴직급여, 소득세액 재계산&quot;">​</a></h3><ul><li>내용 수정 후에는 [과세 재계산]에 체크하고 저장하며, 퇴직급여, 소득세액 등이 재계산 된다.</li></ul><hr><br><p><img src="'+o+'" alt="" data-zoomable="true"></p><h2 id="사용설명-2" tabindex="-1">사용설명 <a class="header-anchor" href="#사용설명-2" aria-label="Permalink to &quot;사용설명&quot;">​</a></h2><h3 id="_1-근속년수-현황" tabindex="-1">1. 근속년수 현황 <a class="header-anchor" href="#_1-근속년수-현황" aria-label="Permalink to &quot;1. 근속년수 현황&quot;">​</a></h3><ul><li>[근속년수] 현황을 표시한다.</li></ul><h3 id="_2-과세-및-세액-계산" tabindex="-1">2.과세 및 세액 계산 <a class="header-anchor" href="#_2-과세-및-세액-계산" aria-label="Permalink to &quot;2.과세 및 세액 계산&quot;">​</a></h3><ul><li>[개정/종전] 규정에 따른 과세 및 세액 계산을 표시한다.</li></ul><hr><br><p><img src="'+h+'" alt="" data-zoomable="true"></p><h2 id="사용설명-3" tabindex="-1">사용설명 <a class="header-anchor" href="#사용설명-3" aria-label="Permalink to &quot;사용설명&quot;">​</a></h2><h3 id="_1-근속년수-현황-1" tabindex="-1">1. 근속년수 현황 <a class="header-anchor" href="#_1-근속년수-현황-1" aria-label="Permalink to &quot;1. 근속년수 현황&quot;">​</a></h3><ul><li>[이연퇴직 소득세액] 계산 내역을 표시한다.</li><li>DB 또는 DC형 관리에서 등록한 정산금액, 연금계좌취급자, 사업자등록번호, 계좌번호가 표시된다.</li><li>직접 입력 또는 수정할 수 있다. (직접 입력시 DB형, DC형 화면에서 추가 입력)</li></ul><h3 id="_2-납부명세-지급내역" tabindex="-1">2. 납부명세, 지급내역 <a class="header-anchor" href="#_2-납부명세-지급내역" aria-label="Permalink to &quot;2. 납부명세, 지급내역&quot;">​</a></h3><ul><li>[납부명세] 내역을 표시한다.</li><li>[지급내역]을 표시한다.</li><li>[금융기관, 지급은행, 계좌번호, 예금주]는 입력 또는 수정할 수 있다.</li><li>[국민연금전환금], [퇴직추계액]은 퇴직급여현황 탭에서 입력된 금액이 표시된다.</li></ul><h3 id="_3-회사지급액-회사반환액" tabindex="-1">3. 회사지급액/회사반환액 <a class="header-anchor" href="#_3-회사지급액-회사반환액" aria-label="Permalink to &quot;3. 회사지급액/회사반환액&quot;">​</a></h3><ul><li><p><strong>회사지급액</strong> = 지급액계 – 회사반환액 – 퇴직추계액</p></li><li><p><strong>회사반환액</strong> = 국민연금전환금 + 차감원천소득세 + 차감원천지방소득세</p></li></ul><hr><br><p><img src="'+n+'" alt="" data-zoomable="true"></p><h2 id="사용설명-4" tabindex="-1">사용설명 <a class="header-anchor" href="#사용설명-4" aria-label="Permalink to &quot;사용설명&quot;">​</a></h2><h3 id="_1-퇴직일자-최계처리일자-입력" tabindex="-1">1. 퇴직일자, 최계처리일자 입력 <a class="header-anchor" href="#_1-퇴직일자-최계처리일자-입력" aria-label="Permalink to &quot;1. 퇴직일자, 최계처리일자 입력&quot;">​</a></h3><ul><li>[퇴직일자, 회계처리일자]를 입력한다.</li></ul><h3 id="_2-전표처리내역-집계" tabindex="-1">2. 전표처리내역 집계 <a class="header-anchor" href="#_2-전표처리내역-집계" aria-label="Permalink to &quot;2. 전표처리내역 집계&quot;">​</a></h3><ul><li>[전표처리내역 집계] 버튼을 클릭하면, 퇴직급여 회계처리 내역이 집계된다.</li></ul><h3 id="_3-전표처리-집계취소" tabindex="-1">3. 전표처리 집계취소 <a class="header-anchor" href="#_3-전표처리-집계취소" aria-label="Permalink to &quot;3. 전표처리 집계취소&quot;">​</a></h3><ul><li>[전표처리 집계취소] 버튼을 클릭하면, 퇴직급여 회계 처리 내역이 취소[삭제]된다.</li></ul><h3 id="_4-회계반영" tabindex="-1">4. 회계반영 <a class="header-anchor" href="#_4-회계반영" aria-label="Permalink to &quot;4. 회계반영&quot;">​</a></h3><ul><li>[회계반영] 버튼을 클릭하면, 회계로 전표가 반영되며, 사원리스트의 [확정] 항목이 확정[체크] 처리된다.</li><li>[회계반영] 전 DC형 또는 DB형 에 계좌가 등록되어 있어야 한다.[IRP계좌가 거래처에 생성되어야 함]</li></ul><h3 id="_5-반영취소" tabindex="-1">5. 반영취소 <a class="header-anchor" href="#_5-반영취소" aria-label="Permalink to &quot;5. 반영취소&quot;">​</a></h3><ul><li>[반영취소] 버튼을 클릭하면, 회계 반영된 전표가 취소되며, 사원리스트의 [확정] 항목의 확정[체크]이 취소 처리된다</li></ul><h3 id="_6-전표조회" tabindex="-1">6. 전표조회 <a class="header-anchor" href="#_6-전표조회" aria-label="Permalink to &quot;6. 전표조회&quot;">​</a></h3><ul><li>[전표조회] 버튼을 클릭하면, [전표조회] 화면이 호출되고, 해당 전표 내역을 조회할 수 있다.</li></ul>',73)])])}const f=r(s,[["render",u]]);export{g as __pageData,f as default};
